"""Incremental exploratory synthesis; E4/E5 recommendations only."""
import json
import numpy as np,pandas as pd
from src.family_6.interpretation import markdown
from . import execution as e

def write(summary):
    p=pd.read_parquet(e.OUT/'tables/oof_predictions.parquet')
    loss=p[p.experiment.isin(['F6-E0','F6-E1','F6-E2'])].copy();loss['SE']=(loss.y_pred-loss.y_true)**2
    paired_loss=loss.pivot(index=[e.ID,'protocol','repeat','fold'],columns='experiment',values='SE').reset_index()
    paired_loss['history_gain']=paired_loss['F6-E0']-paired_loss['F6-E1'];paired_loss['slope_gain']=paired_loss['F6-E0']-paired_loss['F6-E2']
    complementary=[]
    for protocol,g in paired_loss.groupby('protocol'):
        means=g.groupby(e.ID)[['history_gain','slope_gain']].mean();history=means.history_gain>0;slope=means.slope_gain>0
        complementary.append(dict(protocol=protocol,n=len(means),fraction_both=(history&slope).mean(),fraction_history_only=(history&~slope).mean(),fraction_slope_only=(~history&slope).mean(),fraction_neither=(~history&~slope).mean(),gain_correlation=means.history_gain.corr(means.slope_gain)))
    pd.DataFrame(complementary).to_csv(e.OUT/'tables/history_slope_gain_complementarity.csv',index=False)
    paired=pd.read_csv(e.OUT/'tables/paired_metrics_summary.csv');incremental=paired[(paired.baseline=='F6-E0')&paired.candidate.isin(e.SPECS)]
    incremental.to_csv(e.OUT/'tables/refitted_block_ablations_summary.csv',index=False)
    local=pd.read_csv(e.OUT/'tables/intraprofile_metrics_summary.csv');local=local[local.scope.eq('all')]
    fold=pd.read_csv(e.OUT/'tables/paired_fold_contributions.csv');omission=pd.read_csv(e.OUT/'tables/fold_omission_sensitivity.csv')
    influence=pd.read_csv(e.OUT/'tables/influential_parcel_omission.csv');concentration=pd.read_csv(e.OUT/'tables/gain_concentration.csv')
    permutation=pd.read_csv(e.OUT/'tables/conditional_block_permutation_summary.csv');stability=pd.read_csv(e.OUT/'tables/stability_by_outer_fit.csv');usage=pd.read_csv(e.OUT/'tables/feature_usage_stability.csv')
    curve=pd.read_csv(e.OUT/'tables/ALE_support_summary.csv');support=pd.read_csv(e.OUT/'tables/predictor_intraprofile_support.csv')
    assessment=[]
    for name in e.SPECS:
        q=incremental[incremental.candidate.eq(name)].set_index('protocol')
        municipal=float(q.loc['municipality','delta_RMSE']);spatial=float(q.loc['spatial','delta_RMSE'])
        # Descriptive inherited margin, not a newly fitted model/independent confirmation.
        all_harm=float(q[['delta_RMSE','delta_MAE']].max().max())
        omitted=omission[(omission.candidate==name)&(omission.baseline=='F6-E0')]
        gains=int(((fold.candidate==name)&(fold.baseline=='F6-E0')&(fold.protocol=='spatial')&(fold.delta_RMSE<0)).sum())
        locality=local[local.experiment.eq(name)].set_index('protocol').equal_profile_RMSE-local[local.experiment.eq('F6-E0')].set_index('protocol').equal_profile_RMSE
        assessment.append(dict(experiment=name,block=';'.join(e.BLOCKS[name]),delta_RMSE_municipal=municipal,delta_RMSE_spatial=spatial,max_RMSE_MAE_harm=all_harm,n_spatial_blocks_improved=gains,max_spatial_omission_delta=float(omitted[omitted.protocol.eq('spatial')].delta_RMSE.max()),max_municipal_omission_delta=float(omitted[omitted.protocol.eq('municipality')].delta_RMSE.max()),delta_intraprofile_spatial=float(locality.loc['spatial']),delta_intraprofile_municipal=float(locality.loc['municipality']),descriptive_promise=bool(min(municipal,spatial)<=-.01 and all_harm<=.01)))
    assessment=pd.DataFrame(assessment);assessment.to_csv(e.OUT/'tables/block_decision_evidence.csv',index=False)
    hist=assessment.set_index('experiment').loc['F6-E1'];slope=assessment.set_index('experiment').loc['F6-E2']
    # Recommendations are review items, never commands executed by this pipeline.
    e4=bool(hist.descriptive_promise or slope.descriptive_promise)
    choices=[dict(experiment='F6-E4',status='no ejecutado',recommendation='revisar una prueba acotada de complementariedad historia2+pendiente' if e4 else 'posponer: las ganancias espaciales tienen costes municipales importantes',reason='La sinergia no está probada; no se suman beneficios individuales. Ganancias de E1/E2 se concentran en bloques3/4 y ambos perjudican muchas de las mismas parcelas municipales.'),dict(experiment='F6-E5',status='no ejecutado',recommendation='posponer; revisar primero E4 y un contraste de lluvia con bloques idénticos',reason='Mensual7+historia2+pendiente cambia representación y bloques a la vez. Si se reabre, comparar contra E4 aislaría la representación de lluvia; no existe todavía evidencia mensual bagging.')]
    pd.DataFrame(choices).to_csv(e.OUT/'tables/E4_E5_review_decision.csv',index=False)
    text=['# F6-E — Expansión informada de variables','', '**Primera batería completada: E0 recuperado; E1 historia2, E2 pendiente y E3 DTR ajustados. E4/E5 no ejecutados. Referencias y Champion intactos; sin modelo final/PRED.**','', '## Métricas OOF completas','',markdown(summary.pivot(index='experiment',columns='protocol',values='RMSE')), '', 'RMSE en t/ha. Se calculan138 OOF por repetición y luego el promedio de diez repeticiones aleatorias; no se promedian RMSE de folds como métrica primaria. Los folds y repeticiones comparten parcelas: no se declara superioridad estadística. E0 reproduce exactamente F6-01; F6-00 se conserva solo como contexto RF. Champion y etapas se comparan únicamente en los50 folds aleatorios compatibles.', '', '## Utilidad incremental por bloque — ablación con reajuste','',markdown(incremental.set_index(['candidate','protocol'])[['delta_RMSE','delta_MAE','delta_bias']]), '', 'Negativo favorece la extensión. E0 y las extensiones se ajustaron y retunearon independientemente dentro de entrenamiento, con el mismo motor, ocho configuraciones,384 árboles y65 particiones. La ablación de quitar el bloque es el núcleo E0 ya ajustado: se recuperan sus modelos y OOF en lugar de duplicar ajustes idénticos. No es enmascarar columnas de un modelo ampliado.', '', markdown(assessment.set_index('experiment')), '', 'La columna descriptive_promise usa el margen orientativo0.01 de F6 para describir una ganancia geográfica con daños pequeños; no es un gate prospectivo nuevo ni una selección automática. Los nuevos bloques fueron explícitamente autorizados después del cierre compacto y se evaluaron los tres, sin buscar entre1354 variables. La misma fracción max_features se conserva, pero el número efectivo de candidatas cambia cuando cambia la dimensión; esa regularización se registra.','']
    for name in e.SPECS:
        q=incremental[incremental.candidate.eq(name)].set_index('protocol')
        text.append(f"**{name} ({'; '.join(e.BLOCKS[name])}):** ΔRMSE frente a E0 en aleatoria/perfil/municipal/espacial = {', '.join(f'{q.loc[p,"delta_RMSE"]:+.5f}' for p in ['random','climate_profile','municipality','spatial'])}. Las diferencias de MAE y sesgo se reportan aparte; ganancia en un protocolo no implica transferencia uniforme.")
    text+=['', '**La representación sí influye parcialmente:** historia mejora RMSE espacial0.01723 y pendiente0.02350 t/ha frente a E0, con mejoras en cuatro de cinco bloques en ambos casos. No resuelven el conjunto de transferencia: deterioran RMSE municipal0.03729 y0.02383, respectivamente, y sus RMSE espaciales0.74169/0.73542 aún superan0.67878 de C-T3. No se declara una representación ganadora global.', '', '**Historia aporta la señal local más diferenciada de esta batería:** RMSE de diferencias intraperfil espacial0.52004 frente a0.53101 de E0 (igual peso por perfil), y también mejora el ponderado por pares0.78512 frente a0.79265. Esa fortaleza no se repite en aleatoria y el resultado municipal global empeora. Pendiente ofrece una mejora local espacial menor con igual peso, pero no con ponderación por pares. La variación fina de X no garantiza que sea señal predictiva transferible.', '', '**DTR debilita la hipótesis de una partición térmica útil bajo Extra Trees compacto:** empeora los cuatro RMSE y MAE frente a E0. En aleatoria aparece en87.5% de árboles y39.9% de raíces, con impureza descriptiva≈30.2%; esa frecuencia alta contrasta con la falta de utilidad incremental. No demuestra causalidad ni rechaza temperatura bajo otros métodos o representaciones.']
    text+=['', '## Diagnóstico regional, intraperfil y concentración','',markdown(fold[(fold.protocol=='spatial')&(fold.baseline=='F6-E0')].set_index(['candidate','fold'])[['n','delta_RMSE','bias_candidate','bias_base','SSE_gain','bias_squared_gain','error_variance_gain']]), '', 'Se analizan los cinco bloques, incluido3, sin optimizar sobre ninguno. La ganancia SSE se descompone algebraicamente en reducción del sesgo cuadrado y reducción de dispersión de errores (ddof0). Omisiones de bloques, municipios y top1/5/10 casos recalculan OOF existentes, sin reajustar ni eliminar etiquetas de entrenamiento. Los archivos fold_omission_sensitivity.csv y municipality_omission_sensitivity.csv contienen todos los contrastes.', '',markdown(local[local.experiment.isin(['F6-E0',*e.SPECS])].set_index(['experiment','protocol'])[['n_pairs','n_profiles','n_parcels','equal_profile_RMSE','equal_profile_MAE','pair_weighted_RMSE']]), '', 'Diferencias intraperfil únicamente entre predicciones del mismo modelo externo. Hay12 perfiles repetidos; pares dependientes y pesos por perfil/pair distintos. La discriminación local no se confunde con separar perfiles de clima. Historia2 y pendiente varían en los12 perfiles repetidos; DTRstd no varía en ninguno. Por ello E3 puede cambiar particiones entre perfiles, pero no agrega resolución climática intraperfil.', '',markdown(concentration[(concentration.baseline=='F6-E0')&concentration.k.eq(5)].set_index(['candidate','protocol'])[['net_SSE_gain','top_positive_gain','fraction_net_gain','bottom_gain']]), '',markdown(influence[(influence.baseline=='F6-E0')&influence.n_removed.eq(5)].set_index(['candidate','protocol'])[['n_remaining','delta_RMSE_pooled_mean_loss','delta_MAE','SSE_gain']]), '', 'Las omisiones de parcelas usan medias de pérdida por parcela; su RMSE agregado no sustituye la media primaria de RMSE por repetición. Una fracción top5>100% indica compensación por deterioros en otros casos; con ganancia neta negativa esa razón no se interpreta como porcentaje de mejora.', '', '## Qué aporta cada fuente','', 'Historia representa nivel y estacionalidad de la firma histórica NDVI entre meses calendario, no variabilidad interanual ni todo History15/16. Pendiente es un descriptor estático del terreno; puede actuar como proxy territorial y no demuestra un mecanismo hídrico. DTRstd describe variabilidad temporal de la amplitud térmica; el campo no proporciona diferencias dentro de perfiles climáticos idénticos. Las asociaciones anteriores justificaron las hipótesis, pero únicamente las ablaciones OOF determinan utilidad incremental con Extra Trees.', '',markdown(permutation.set_index(['experiment','protocol'])), '', 'Permutación: el bloque histórico se mueve conjuntamente, manteniendo sus dos columnas emparejadas, entre parcelas del mismo perfil dentro de validación. Se repite diez veces si≥10 parcelas tienen variación del bloque. Condiciona sobre clima, no sobre todos los demás predictores; es dependencia predictiva descriptiva, no mecanismo causal. Un bloque constante o insuficiente se marca no identificable. DTRstd tiene precisamente ese límite: no se interpreta un cero mecánico como irrelevancia. No se usan permutaciones marginales que mezclen lluvia/DTR sin soporte.', '', 'ALE e interacciones se limitan a regiones respaldadas: q95 de distancia leave-one-out en entrenamiento define el radio; cada bin/celda requiere≥5 parcelas y≥80% de esquinas dentro del radio. Solo esas esquinas se predicen. Si falta soporte no se conecta la curva a través del hueco; se muestran cambios locales respaldados cuando existen. Distancias y cuantiles son propios de cada transformación/fold, no directamente comparables entre representaciones. Esta vecindad es aproximada y no certifica soporte físico ni causalidad. Se conserva el detalle por fit y la fracción respaldada en effects_by_outer_fit.csv, interactions_by_outer_fit.csv y ALE_support_summary.csv.', '', 'Interacciones examinadas exclusivamente: mayo×hist_mean, hist_mean×hist_std, mayo×pendiente, lluvia_total×pendiente, HHI×DTR y mayo×DTR. No se escanean pares adicionales. Umbrales en unidades originales, soporte de hojas y frecuencias de uso por árbol se conservan con dispersión entre ajustes. Frecuencia e impureza son descripciones, no evidencia suficiente de utilidad ni causalidad.','', '## Estabilidad y recomendaciones','',markdown(stability[stability.prefix_n_trees.eq(256)].groupby(['experiment','protocol']).agg(mean_RMS_difference=('RMS_prediction_difference_from_384','mean'),max_RMS_difference=('RMS_prediction_difference_from_384','max'))), '', 'La variación entre prefijos256 y384 señala sensibilidad Monte Carlo;384 permanece fijo y no se abre otra búsqueda de árboles como respuesta a los resultados. La dispersión entre árboles no es un intervalo predictivo observacional.', '',markdown(pd.DataFrame(choices).set_index('experiment')), '', 'E4/E5 son propuestas para revisión, sin ejecución. Combinar ganancias individuales no garantiza sinergia; E5 debe contrastarse con E4 si se quiere atribuir la diferencia a la representación de lluvia. Una decisión basada en estas OOF externas continúa siendo exploratoria, no confirmación independiente ni promoción global.', '', '**F7:** mantener como alternativa una comparación CatBoost/XGBoost directa con núcleo y los mismos bloques predefinidos; revisión técnica antes de ejecutar. No se asume que boosting resolverá la transferencia. Su selección y cualquier early stopping deben quedar dentro de entrenamiento externo. No se instala ni ejecuta F7 aquí.']
    text+=['', '## Síntesis de hipótesis y decisión revisada','', 'La ganancia espacial de historia procede sobre todo del bloque3 (2.859 de3.569 SSE neta,≈80%); la de pendiente, del bloque4 (3.254 de4.846,≈67%). Al omitir esos bloques todavía queda mejora RMSE, pero se reduce a0.00544 para historia sin bloque3 y0.00910 para pendiente sin bloque4. Ambas ganancias espaciales sobreviven a omitir los cinco casos de mayor beneficio; son menos concentradas que las pequeñas ganancias aleatorias originales de F6.', '', 'Existe complementariedad espacial descriptiva:48.6% de parcelas mejoran con ambos bloques;9.4% solo con historia y13.0% solo con pendiente. En municipal63.0% empeoran con ambos. Esa coincidencia de deterioros es la principal objeción a recomendar E4 de inmediato. Los porcentajes usan medias de pérdida por parcela y no construyen un ensamble ni predicciones combinadas. La sinergia de un modelo conjunto permanece desconocida.', '', 'Las permutaciones indican dependencia local pequeña de historia y pendiente (aumentos MSE, cambios MAE pequeños y a menudo negativos). La frecuencia de uso es alta: historia_mean83.2%, historia_std91.5%, pendiente93.9% de árboles aleatorios; eso no revierte sus costes municipales. Las hojas conservan al menos cinco muestras, con medianas7–8 para E1/E2. El soporte multivariado es limitado: ninguna curva ALE completa de pendiente o DTR supera el gate, y la historia solo permite curvas completas en un fit de65 para su media y ninguno para std. Se entregan cambios locales y celdas respaldadas, sin llenar los huecos.', '', '**Recomendación explícita:** posponer E4/E5 y preparar la propuesta F7 como siguiente línea. Conservar historia y pendiente como hipótesis de fortalezas espaciales/locales, no como añadidos aprobados a un modelo final. No hay evidencia equilibrada municipal/espacial para recomendar ampliar inmediatamente bagging. Si se decide reabrir F6 posteriormente, E4 debería preceder a E5 y abordar expresamente los deterioros municipales compartidos. Este resultado apoya una limitación parcial de la representación compacta, debilita el DTR como extensión Extra Trees evaluada y no rechaza todos los bloques históricos, toda topografía o todos los bosques.']
    (e.OUT/'report/synthesis.md').write_text('\n'.join(text)+'\n',encoding='utf8')
    decision=dict(recommendation='defer_E4_E5_prepare_F7_proposal',executed=['F6-E1','F6-E2','F6-E3'],recovered='F6-E0 exact F6-01',E4_E5=choices,champion_promoted=False,PRED_predictions=False,F7_executed=False,statistical_superiority_claimed=False)
    (e.OUT/'report/decision.json').write_text(json.dumps(decision,indent=2),encoding='utf8')
